[
  {
    "title": "indistinct-stance-directions",
    "claim": "In image #3, both horizontal STANCE hints say 'step', while the neighboring TECHNIQUE hints distinguish 'back' from 'forward'.",
    "reason": "The stance hints do not explain which direction closes distance and which creates space.",
    "suggest": "Use 'back step' and 'forward step' for the pictured facing, keeping those labels synchronized with the fighter's facing."
  },
  {
    "title": "misplaced-combination-symbol",
    "claim": "In image #6, the '+' occupies an otherwise unlabeled cell beside RETREATING within the STANCE legend rather than separating the STANCE and TECHNIQUE groups.",
    "reason": "Its placement makes the instruction to combine the two sticks harder to understand.",
    "suggest": "Place 'One stance + one technique' in a dedicated full-width instruction between the two groups."
  },
  {
    "title": "ambiguous-technique-dimming",
    "claim": "In image #6, the Spinning Back Kick row is visibly dimmer than the preceding rows, without a visible label explaining its status.",
    "reason": "A player could mistake a scroll-edge treatment for an unavailable technique; the still cannot establish which causes the dimming.",
    "suggest": "Keep readable technique rows undimmed and confine any scroll-edge fade to a gutter that does not cover their text or input symbols."
  },
  {
    "title": "missing-desktop-key-legends",
    "claim": "In desktop image #9, the two sticks show direction marks and STANCE/TECHNIQUE labels, but no keyboard bindings are visible.",
    "reason": "A keyboard player cannot discover the corresponding keys from this screen.",
    "suggest": "Add compact legends beside each stick using the actual configured keyboard bindings, while retaining the touch controls."
  },
  {
    "title": "result-countdown-without-cancel",
    "claim": "In images #8 and #18, REMATCH appears above 'STARTING IN 8', with no visible control to cancel the indicated start.",
    "reason": "A player reviewing the result has no visible way to request more time.",
    "suggest": "Keep REMATCH as the primary action and add a clearly labeled 'Stay on results' control that cancels the countdown."
  }
]
